#!/usr/bin/env python3
# Generate Mia's English lessons 21-50 by cloning the a1s_03 template and
# swapping only the variable blocks. Engine/CSS/warm-up/words panels stay identical.
import re, os
DIR = "/Users/malcolmtheteacher/Documents/01_Work/gitsite"
TPL = open(os.path.join(DIR, "a1s_03_where.html"), encoding="utf-8").read()

M1 = "mia_english_dashboard.html"      # morelink 1 (always exists)
M2 = "CEFR_Grammar_Dashboard.html"     # morelink 2 (always exists)

def story_html(img1, alt1, img2, alt2, lines):
    half = max(1, len(lines)*2//3)
    top = "".join("            <p>%s</p>\n" % l for l in lines[:half])
    bot = "".join("            <p>%s</p>\n" % l for l in lines[half:])
    return (
        '            <img class="scene" src="%s" alt="%s" onerror="ph(this)">\n%s'
        '            <img class="scene" src="%s" alt="%s" onerror="ph(this)">\n%s'
        % (img1, alt1, top, img2, alt2, bot))

def build_file(n, slug, title, sub, story_h2, story_lines, img1, alt1, img2, alt2,
               tip1, pat_h2, pat_build, pat_tip, yt_lead, yt_build, yt_label, yt_ph,
               checklist, words):
    name = "Lesson %d · %s" % (n, title)
    s = TPL
    # title + meta
    s = s.replace("<title>Mia's English · Lesson 3 · Where is it?</title>",
                  "<title>Mia's English · Lesson %d · %s</title>" % (n, title))
    s = re.sub(r'<meta name="description"[^>]*>',
               '<meta name="description" content="Mia\'s English — Lesson %d: %s. %s">' % (n, title, sub.replace('"',"'")),
               s, count=1)
    # header block
    s = re.sub(r'<header>.*?</header>',
        '<header>\n        <div class="step">Mia\'s English · Lesson %d</div>\n'
        '        <h1>%s</h1>\n        <p>%s</p>\n    </header>' % (n, title, sub),
        s, count=1, flags=re.S)
    # story panel (between <!-- STORY --> and <!-- WORDS -->)
    story = (
        '    <!-- STORY -->\n    <div class="panel" id="p1">\n'
        '        <h2>%s <span class="em">📖</span></h2>\n'
        '        <p class="lead">Read it slowly. Say the words out loud.</p>\n'
        '        <div class="story">\n%s        </div>\n'
        '        <div class="tip"><b>Notice:</b> %s</div>\n'
        '        <div class="center"><button class="btn btn-primary" onclick="showTab(2)">Learn the words →</button></div>\n'
        '    </div>\n\n' % (story_h2, story_html(img1, alt1, img2, alt2, story_lines), tip1))
    s = re.sub(r'    <!-- STORY -->.*?\n\n(    <!-- WORDS -->)', story + r'\1', s, count=1, flags=re.S)
    # pattern panel
    pat = (
        '    <!-- PATTERN -->\n    <div class="panel" id="p3">\n'
        '        <h2>%s <span class="em">🧩</span></h2>\n'
        '        <p class="lead">Look at the pattern, then use it.</p>\n'
        '        <div class="build">\n%s        </div>\n'
        '        <div class="tip">%s</div>\n'
        '        <a class="morelink" href="%s">🗺️ <span>Back to all Mia lessons</span><span class="go">Open →</span></a>\n'
        '        <a class="morelink" href="%s">📚 <span>The full grammar course</span><span class="go">Open →</span></a>\n'
        '    </div>\n\n' % (pat_h2, pat_build, pat_tip, M1, M2))
    s = re.sub(r'    <!-- PATTERN -->.*?\n\n(    <!-- YOUR TURN -->)', pat + r'\1', s, count=1, flags=re.S)
    # your turn panel
    checks = "".join("            <li>%s</li>\n" % c for c in checklist)
    yt = (
        '    <!-- YOUR TURN -->\n    <div class="panel" id="p4">\n'
        '        <h2>Now you <span class="em">🗣️</span></h2>\n'
        '        <p class="lead">%s</p>\n'
        '        <div class="build">\n%s        </div>\n'
        '        <label class="f">%s</label>\n'
        '        <input class="blank" placeholder="%s">\n\n'
        '        <h3 style="color:var(--teal-d);margin:18px 0 6px;">Practise today\'s words</h3>\n'
        '        <p class="lead" style="margin-bottom:8px">Tap to check yourself, then rate how well you knew each one.</p>\n'
        '        <div class="center"><button class="btn btn-ghost" onclick="reviewToday()">Review today\'s words 🔁</button></div>\n'
        '        <div id="turnReview" style="margin-top:14px"></div>\n\n'
        '        <h3 style="color:var(--teal-d);margin:18px 0 6px;">Before you go</h3>\n'
        '        <ul class="checklist">\n%s        </ul>\n'
        '        <div class="tip" style="margin-top:16px"><b>See you next time.</b> Today\'s words join your Warm-up. Little by little, they become yours forever. 🔁</div>\n'
        '    </div>\n\n' % (yt_lead, yt_build, yt_label, yt_ph, checks))
    s = re.sub(r'    <!-- YOUR TURN -->.*?\n\n(    <footer>)', yt + r'\1', s, count=1, flags=re.S)
    # footer
    s = s.replace("<footer>Mia's English · A1 Story Journey · Lesson 3</footer>",
                  "<footer>Mia's English · A1 Story Journey · Lesson %d</footer>" % n)
    # LESSON_NAME + array
    s = s.replace('var LESSON_NAME="Lesson 3 · Where is it?";',
                  'var LESSON_NAME="%s";' % name)
    arr = "var LESSON=[\n" + "".join(
        "    ['%s',\"%s\",'%s','%s'],\n" % (w[0], w[1], w[2], w[3]) for w in words) + "];"
    s = re.sub(r'var LESSON=\[.*?\];', arr, s, count=1, flags=re.S)
    open(os.path.join(DIR, "a1s_%02d_%s.html" % (n, slug)), "w", encoding="utf-8").write(s)
    return "a1s_%02d_%s.html" % (n, slug), name, [w[1] for w in words]

# ---- content for lessons 21-50 ----
def w(i,f,b,e): return ("l%d_%s"%(i,re.sub(r'[^a-z]','',f.lower())[:8] or "w"), f, b, e)
L = []
def add(**k): L.append(k)

