out=[]
for d in L:
    fn,name,words = build_file(**d)
    out.append((d['n'],fn,name,len(words)))
for n,fn,name,c in out:
    print("%d  %-24s  %s  (%d words)" % (n,fn,name,c))
print("\nGenerated %d lessons" % len(out))
